package org.circus.core;
import java.io.*;
import java.util.*;
/** Raw OS DWORD owner versus typed scalar registry. No physical API is faked
 *as successfully performed by declaring its initial BSS bytes. */
public final class Pc1OsWordsTests {
 private static int checks;private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private interface Work{void run()throws IOException;}
 private static void reject(Work work,String text)throws IOException{boolean failed=false;try{work.run();}catch(IOException expected){failed=expected.getMessage().contains(text);}check(failed,"precise "+text);}
 private static final class Provider implements Pc1OsRegistry.Binding {final long handle;boolean live=true,fail;int published;Provider(long value){handle=value;}public long physicalHandle(){return handle;}public boolean live(){return live;}public String contractId(){return "explicit OS word fixture V1";}public byte[] restorationProof(){return new byte[]{3,5,7};}public void published(int word)throws IOException{published++;if(fail)throw new IOException("physical mapping publication unavailable");}}
 private static Pc1NativeMemory bus(){return new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){final byte[] raw=new byte[Pc1NativeSettings.SIZE];public int read(int n){return raw[n]&255;}public void write(int n,int value){raw[n]=(byte)value;}});}
 private static Pc1GuestAddressSpace space()throws IOException{return new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());}
 private static Pc1GuestAddressSpace.ExternalOwner key(String id)throws IOException{return new Pc1GuestAddressSpace.ExternalOwner("PC1_OS_WORD_FIXTURE",id);}
 private static byte[] save(Pc1OsWords words)throws IOException{ByteArrayOutputStream output=new ByteArrayOutputStream();words.save(new DataOutputStream(output));return output.toByteArray();}
 public static int run()throws Exception{
  checks=0;Pc1GuestAddressSpace space=space();Pc1NativeMemory memory=bus();space.bindTo(memory);Pc1OsRegistry registry=new Pc1OsRegistry(space);Pc1OsWords words=new Pc1OsWords(memory,registry);check(words.rawWord(Pc1OsWords.HWND)==0&&words.knownByteMask(Pc1OsWords.HWND)==15,"only actual loaded-zero OS BSS cells declared; no physical window creation claimed");Provider font22=new Provider(0x12345678),font40=new Provider(0x22345678),bitmap=new Provider(0x32345678);Pc1OsRegistry.Scalar a=words.publish(Pc1OsWords.FONT22,Pc1OsRegistry.Kind.FONT,key("font22"),font22),b=words.publish(Pc1OsWords.FONT40,Pc1OsRegistry.Kind.FONT,key("font40"),font40),c=words.publish(Pc1OsWords.GLYPH_BITMAP,Pc1OsRegistry.Kind.BITMAP,key("bitmap"),bitmap);check(words.rawWord(Pc1OsWords.FONT22)==a.rawWord&&words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).physicalHandle()==font22.handle,"native MOV publishes exactly one word consumed by late resolution");words.rawWord(Pc1OsWords.FONT22,b.rawWord);check(words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).physicalHandle()==font40.handle&&font22.live,"raw overwrite selects another existing font and does not close lost/orphaned original");words.rawWord(Pc1OsWords.FONT22,c.rawWord);check(words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).object.kind==Pc1OsRegistry.Kind.BITMAP,"SelectObject receives known GDI kind instead of stale fonts22 table");
  int index=Pc1OsWords.FONT22-(Pc1FrameLayout.LIVE_BASE+Pc1FrameLayout.BANK90_OFFSET);for(int n=0;n<4;n++)memory.writeBank90(index+n,b.rawWord>>>(n*8));check(words.rawWord(Pc1OsWords.FONT22)==b.rawWord&&words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).object==b,"ordinary byte aliases update same raw DWORD, without an after-command mirror");memory.writeAddress(Pc1OsWords.FONT22,0xa9);check(words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.UNKNOWN,"partially overwritten known word never falls back to old font object");words.rawWord(Pc1OsWords.FONT22,0);check(words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.NULL,"explicit raw NULL remains API-specific, not implicit known-success0");
  Provider wide=new Provider(0x123456789000L);Pc1OsRegistry.Scalar w=words.publish(Pc1OsWords.HWND,Pc1OsRegistry.Kind.WINDOW,key("window"),wide);check(w.authority==Pc1OsRegistry.Authority.GUEST32_OPAQUE&&words.rawWord(Pc1OsWords.HWND)==w.rawWord&&words.resolve(Pc1OsWords.HWND,Pc1OsRegistry.Domain.USER).physicalHandle()==wide.handle,"wide actual object uses common guest opaque scalar without truncation");wide.live=false;check(words.resolve(Pc1OsWords.HWND,Pc1OsRegistry.Domain.USER).status==Pc1OsRegistry.Status.CLOSED&&words.rawWord(Pc1OsWords.HWND)==w.rawWord,"native close leaves stale DWORD while current provider reports closed");
  Pc1HeapLease backing=Pc1HeapLease.observed64(0x55550000000L,new byte[]{11,23,37,51},"explicit physical-byte fixture; no OS call");words.publishMemory(Pc1OsWords.GLYPH_BITS,backing,key("actual-DIB-bytes"));int pointer=words.rawWord(Pc1OsWords.GLYPH_BITS);space.write(pointer+1,79);check(backing.readU8(1)==79&&registry.lookup(pointer,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.UNKNOWN,"DIB bits pointer is memory lease, not HBITMAP/ABI scalar");
  words.rawWord(Pc1OsWords.FONT22,b.rawWord);byte[] saved=save(words);words.rawWord(Pc1OsWords.FONT22,a.rawWord);font40.live=false;words.restore(Pc1OsWords.loadImage(new DataInputStream(new ByteArrayInputStream(saved))));check(words.rawWord(Pc1OsWords.FONT22)==b.rawWord&&words.resolve(Pc1OsWords.FONT22,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.CLOSED,"raw cell restore does not restore physical liveness or object registry separately");
  words.unknown(Pc1OsWords.PROCESS_HEAP,"physical64 HANDLE cannot yet be associated");check(words.knownByteMask(Pc1OsWords.PROCESS_HEAP)==0,"unknown result publication never writes successful-looking zero");reject(()->memory.readAddress(Pc1OsWords.PROCESS_HEAP),"unknown after physical publication");memory.writeAddress(Pc1OsWords.PROCESS_HEAP,0x78);check(words.knownByteMask(Pc1OsWords.PROCESS_HEAP)==1,"one-byte alias establishes only that byte");reject(()->words.rawWord(Pc1OsWords.PROCESS_HEAP),"unknown after physical publication");for(int n=1;n<4;n++)memory.writeAddress(Pc1OsWords.PROCESS_HEAP+n,0x11*n);check(words.rawWord(Pc1OsWords.PROCESS_HEAP)==0x33221178&&words.knownByteMask(Pc1OsWords.PROCESS_HEAP)==15,"four explicit byte writes establish current raw word without inventing a handle");
  words.unknown(Pc1OsWords.EFFECT_DC,"required actual GetDC association unavailable");byte[] unknown=save(words);words.rawWord(Pc1OsWords.EFFECT_DC,0);words.restore(Pc1OsWords.loadImage(new DataInputStream(new ByteArrayInputStream(unknown))));reject(()->words.rawWord(Pc1OsWords.EFFECT_DC),"required actual GetDC association");
  Provider failure=new Provider(0x77770000000L);failure.fail=true;reject(()->words.publish(Pc1OsWords.FONT12,Pc1OsRegistry.Kind.FONT,key("failed-font"),failure),"publication unavailable");check(words.knownByteMask(Pc1OsWords.FONT12)==0&&failure.published==1,"failed provider retains precise unknown native publication state");reject(()->words.rawWord(Pc1OsWords.FONT12),"unknown after physical publication");reject(()->words.rawWord(0x42ab1c,3),"not an owned OS DWORD");
  Pc1NativeMemory wrong=bus();new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1()).bindTo(wrong);reject(()->new Pc1OsWords(wrong,registry),"different guest domains");return checks;
 }
 public static void main(String[] args)throws Exception{System.out.println("PASS Pc1OsWordsTests "+run());}
}
